// Workaround error del logo de Mercap
cy.get('.application-footer-logo-symbol').then($logos => {
  cy.get('.collapse.navbar-collapse, .application-footer-container.hidden-xs.hidden-sm').then($containers => {
    const containersArray = $containers.toArray();
    const isLogoInsideContainer = [...$logos].some(logo => containersArray.some(container => container.contains(logo)));
    if (!isLogoInsideContainer) {
      cy.visit(_constants.default.PEPPER_LOCATION);
    } else {
      cy.log('El logo está en la ubicación correcta');
    }
  });
});
// Guardar en una variable la versión de Pepper
cy.get('.pull-right .application-footer-link').invoke('text').then(text => {
  const PEPPER_VERSION = text.trim();
  cy.writeFile('pepper-version.txt', PEPPER_VERSION);
});
